"use client"

import { useTheme } from "next-themes"
import { Toaster as Sonner, type ToasterProps } from "sonner"
import { 
  CheckmarkCircle01Icon, 
  InformationCircleIcon, 
  AlertCircleIcon, 
  CancelCircleIcon, 
  Loading03Icon 
} from "@hugeicons/core-free-icons"
import { HugeiconsIcon } from "@hugeicons/react"

const Toaster = ({ ...props }: ToasterProps) => {
  const { theme = "system" } = useTheme()

  return (
    <Sonner
      theme={theme as ToasterProps["theme"]}
      className="toaster group"
      icons={{
        success: (
          <HugeiconsIcon icon={CheckmarkCircle01Icon} className="size-4" strokeWidth={1.5} />
        ),
        info: (
          <HugeiconsIcon icon={InformationCircleIcon} className="size-4" strokeWidth={1.5} />
        ),
        warning: (
          <HugeiconsIcon icon={AlertCircleIcon} className="size-4" strokeWidth={1.5} />
        ),
        error: (
          <HugeiconsIcon icon={CancelCircleIcon} className="size-4" strokeWidth={1.5} />
        ),
        loading: (
          <HugeiconsIcon icon={Loading03Icon} className="size-4 animate-spin" strokeWidth={1.5} />
        ),
      }}
      style={
        {
          "--normal-bg": "var(--popover)",
          "--normal-text": "var(--popover-foreground)",
          "--normal-border": "var(--border)",
          "--border-radius": "var(--radius)",
        } as React.CSSProperties
      }
      toastOptions={{
        classNames: {
          toast: "cn-toast",
        },
      }}
      {...props}
    />
  )
}

export { Toaster }
